//! Parser and writer for the standard WireGuard `.conf` format.
//!
//! tvpn profiles *are* WireGuard configs, so any config exported by a
//! WireGuard provider, `wg-quick`, wg-easy, etc. works as-is, and configs
//! generated by `tvpn server add-peer` work in the official WireGuard apps.

use crate::keys::Key;
use ipnet::IpNet;
use std::fmt::{self, Write as _};
use std::net::{IpAddr, SocketAddr};
use std::str::FromStr;

#[derive(Debug, Clone, PartialEq)]
pub struct Config {
    pub interface: Interface,
    pub peers: Vec<Peer>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Interface {
    pub private_key: Key,
    pub addresses: Vec<IpNet>,
    pub listen_port: Option<u16>,
    pub dns: Vec<IpAddr>,
    pub dns_search: Vec<String>,
    pub mtu: Option<u16>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Peer {
    /// Optional friendly name, stored as a `# Name = ...` comment.
    pub name: Option<String>,
    pub public_key: Key,
    pub preshared_key: Option<Key>,
    pub allowed_ips: Vec<IpNet>,
    pub endpoint: Option<Endpoint>,
    pub persistent_keepalive: Option<u16>,
}

/// `host:port` as written in the config; resolved at connect time.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Endpoint {
    pub host: String,
    pub port: u16,
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
#[error("line {line}: {message}")]
pub struct ParseError {
    pub line: usize,
    pub message: String,
}

/// Successful parse result plus non-fatal warnings (ignored keys, ...).
#[derive(Debug)]
pub struct Parsed {
    pub config: Config,
    pub warnings: Vec<String>,
}

pub const DEFAULT_MTU: u16 = 1420;

impl Endpoint {
    pub async fn resolve(&self) -> std::io::Result<Vec<SocketAddr>> {
        let addrs: Vec<SocketAddr> =
            tokio::net::lookup_host((self.host.as_str(), self.port)).await?.collect();
        Ok(addrs)
    }

    /// Resolve and pick one address, preferring IPv4 (works on more networks).
    pub async fn resolve_preferred(&self) -> std::io::Result<SocketAddr> {
        let addrs = self.resolve().await?;
        addrs.iter().find(|a| a.is_ipv4()).or_else(|| addrs.first()).copied().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::NotFound, format!("no addresses found for {}", self.host))
        })
    }
}

impl FromStr for Endpoint {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let s = s.trim();
        let (host, port) = if let Some(rest) = s.strip_prefix('[') {
            let (host, port) = rest
                .split_once("]:")
                .ok_or_else(|| format!("invalid endpoint `{s}` (expected [ipv6]:port)"))?;
            (host, port)
        } else {
            s.rsplit_once(':').ok_or_else(|| format!("invalid endpoint `{s}` (expected host:port)"))?
        };
        if host.is_empty() {
            return Err(format!("invalid endpoint `{s}`: missing host"));
        }
        if host.contains(':') && !s.starts_with('[') {
            return Err(format!("invalid endpoint `{s}`: wrap IPv6 addresses in brackets"));
        }
        let port: u16 = port.parse().map_err(|_| format!("invalid endpoint `{s}`: bad port `{port}`"))?;
        if port == 0 {
            return Err(format!("invalid endpoint `{s}`: port must not be 0"));
        }
        Ok(Endpoint { host: host.to_string(), port })
    }
}

impl fmt::Display for Endpoint {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.host.contains(':') {
            write!(f, "[{}]:{}", self.host, self.port)
        } else {
            write!(f, "{}:{}", self.host, self.port)
        }
    }
}

/// Parse an address or network. A bare address becomes a host route (/32, /128).
pub fn parse_net(s: &str) -> Result<IpNet, String> {
    let s = s.trim();
    if let Ok(net) = s.parse::<IpNet>() {
        return Ok(net);
    }
    if let Ok(ip) = s.parse::<IpAddr>() {
        return Ok(IpNet::from(ip));
    }
    Err(format!("invalid IP address or network `{s}`"))
}

fn split_list(v: &str) -> impl Iterator<Item = &str> {
    v.split(',').map(str::trim).filter(|s| !s.is_empty())
}

#[derive(PartialEq)]
enum Section {
    None,
    Interface,
    Peer,
}

#[derive(Default)]
struct PeerBuilder {
    line: usize,
    name: Option<String>,
    public_key: Option<Key>,
    preshared_key: Option<Key>,
    allowed_ips: Vec<IpNet>,
    endpoint: Option<Endpoint>,
    persistent_keepalive: Option<u16>,
}

/// Keys understood by wg-quick that tvpn deliberately does not act on.
const IGNORED_INTERFACE_KEYS: &[&str] =
    &["table", "preup", "postup", "predown", "postdown", "saveconfig", "fwmark"];

impl Config {
    pub fn parse(text: &str) -> Result<Parsed, ParseError> {
        let mut warnings = Vec::new();
        let mut section = Section::None;
        let mut seen_interface = false;

        let mut private_key: Option<Key> = None;
        let mut addresses = Vec::new();
        let mut listen_port = None;
        let mut dns = Vec::new();
        let mut dns_search = Vec::new();
        let mut mtu = None;
        let mut peers: Vec<PeerBuilder> = Vec::new();

        for (idx, raw) in text.lines().enumerate() {
            let line_no = idx + 1;
            let err = |message: String| ParseError { line: line_no, message };
            let raw = raw.trim_start_matches('\u{feff}').trim();
            if raw.is_empty() {
                continue;
            }
            if let Some(comment) = raw.strip_prefix('#') {
                if section == Section::Peer
                    && let Some(name) = parse_name_comment(comment)
                    && let Some(p) = peers.last_mut()
                {
                    p.name = Some(name);
                }
                continue;
            }
            let line = raw.split('#').next().unwrap_or("").trim();
            if line.is_empty() {
                continue;
            }

            if line.starts_with('[') {
                let name = line
                    .strip_prefix('[')
                    .and_then(|l| l.strip_suffix(']'))
                    .ok_or_else(|| err(format!("malformed section header `{line}`")))?
                    .trim()
                    .to_ascii_lowercase();
                match name.as_str() {
                    "interface" => {
                        if seen_interface {
                            return Err(err("duplicate [Interface] section".into()));
                        }
                        seen_interface = true;
                        section = Section::Interface;
                    }
                    "peer" => {
                        peers.push(PeerBuilder { line: line_no, ..Default::default() });
                        section = Section::Peer;
                    }
                    other => return Err(err(format!("unknown section [{other}]"))),
                }
                continue;
            }

            let (key, value) =
                line.split_once('=').ok_or_else(|| err(format!("expected `Key = Value`, found `{line}`")))?;
            let key_lc = key.trim().to_ascii_lowercase();
            let value = value.trim();

            match section {
                Section::None => {
                    return Err(err(format!("`{}` appears before any section", key.trim())));
                }
                Section::Interface => match key_lc.as_str() {
                    "privatekey" => {
                        private_key = Some(value.parse().map_err(|e| err(format!("PrivateKey: {e}")))?)
                    }
                    "address" => {
                        for part in split_list(value) {
                            addresses.push(parse_net(part).map_err(|e| err(format!("Address: {e}")))?);
                        }
                    }
                    "listenport" => {
                        listen_port = Some(
                            value
                                .parse()
                                .map_err(|_| err(format!("ListenPort: invalid port `{value}`")))?,
                        )
                    }
                    "dns" => {
                        for part in split_list(value) {
                            match part.parse::<IpAddr>() {
                                Ok(ip) => dns.push(ip),
                                Err(_) if is_domain(part) => dns_search.push(part.to_string()),
                                Err(_) => return Err(err(format!("DNS: invalid entry `{part}`"))),
                            }
                        }
                    }
                    "mtu" => {
                        let v: u16 = value
                            .parse()
                            .map_err(|_| err(format!("MTU: invalid value `{value}`")))?;
                        if !(576..=9000).contains(&v) {
                            return Err(err(format!("MTU: {v} is outside the range 576-9000")));
                        }
                        mtu = Some(v);
                    }
                    k if IGNORED_INTERFACE_KEYS.contains(&k) => warnings.push(format!(
                        "line {line_no}: `{}` is not supported by tvpn and was ignored (tvpn never runs hook scripts)",
                        key.trim()
                    )),
                    _ => warnings.push(format!("line {line_no}: unknown key `{}` ignored", key.trim())),
                },
                Section::Peer => {
                    let p = peers.last_mut().expect("peer section exists");
                    match key_lc.as_str() {
                        "publickey" => {
                            p.public_key =
                                Some(value.parse().map_err(|e| err(format!("PublicKey: {e}")))?)
                        }
                        "presharedkey" => {
                            p.preshared_key =
                                Some(value.parse().map_err(|e| err(format!("PresharedKey: {e}")))?)
                        }
                        "allowedips" => {
                            for part in split_list(value) {
                                p.allowed_ips
                                    .push(parse_net(part).map_err(|e| err(format!("AllowedIPs: {e}")))?);
                            }
                        }
                        "endpoint" => {
                            p.endpoint = Some(value.parse().map_err(|e: String| err(e))?);
                        }
                        "persistentkeepalive" => {
                            p.persistent_keepalive = if value.eq_ignore_ascii_case("off") {
                                None
                            } else {
                                let v: u16 = value.parse().map_err(|_| {
                                    err(format!("PersistentKeepalive: invalid value `{value}`"))
                                })?;
                                (v > 0).then_some(v)
                            };
                        }
                        _ => warnings
                            .push(format!("line {line_no}: unknown key `{}` ignored", key.trim())),
                    }
                }
            }
        }

        if !seen_interface {
            return Err(ParseError { line: 0, message: "missing [Interface] section".into() });
        }
        let private_key =
            private_key.ok_or(ParseError { line: 0, message: "[Interface] is missing PrivateKey".into() })?;

        let mut out_peers = Vec::with_capacity(peers.len());
        for p in peers {
            let public_key = p
                .public_key
                .ok_or(ParseError { line: p.line, message: "[Peer] is missing PublicKey".into() })?;
            out_peers.push(Peer {
                name: p.name,
                public_key,
                preshared_key: p.preshared_key,
                allowed_ips: p.allowed_ips,
                endpoint: p.endpoint,
                persistent_keepalive: p.persistent_keepalive,
            });
        }

        Ok(Parsed {
            config: Config {
                interface: Interface { private_key, addresses, listen_port, dns, dns_search, mtu },
                peers: out_peers,
            },
            warnings,
        })
    }

    /// Serialize back to the WireGuard format.
    pub fn to_wg_string(&self) -> String {
        let mut s = String::new();
        let i = &self.interface;
        s.push_str("[Interface]\n");
        let _ = writeln!(s, "PrivateKey = {}", i.private_key.to_base64());
        if !i.addresses.is_empty() {
            let _ = writeln!(s, "Address = {}", join(&i.addresses));
        }
        if let Some(port) = i.listen_port {
            let _ = writeln!(s, "ListenPort = {port}");
        }
        if !i.dns.is_empty() || !i.dns_search.is_empty() {
            let mut entries: Vec<String> = i.dns.iter().map(ToString::to_string).collect();
            entries.extend(i.dns_search.iter().cloned());
            let _ = writeln!(s, "DNS = {}", entries.join(", "));
        }
        if let Some(mtu) = i.mtu {
            let _ = writeln!(s, "MTU = {mtu}");
        }
        for p in &self.peers {
            s.push_str("\n[Peer]\n");
            if let Some(name) = &p.name {
                let _ = writeln!(s, "# Name = {name}");
            }
            let _ = writeln!(s, "PublicKey = {}", p.public_key.to_base64());
            if let Some(psk) = &p.preshared_key {
                let _ = writeln!(s, "PresharedKey = {}", psk.to_base64());
            }
            if !p.allowed_ips.is_empty() {
                let _ = writeln!(s, "AllowedIPs = {}", join(&p.allowed_ips));
            }
            if let Some(ep) = &p.endpoint {
                let _ = writeln!(s, "Endpoint = {ep}");
            }
            if let Some(ka) = p.persistent_keepalive {
                let _ = writeln!(s, "PersistentKeepalive = {ka}");
            }
        }
        s
    }

    /// Checks that make sense for connecting as a client.
    pub fn validate_client(&self) -> Result<(), String> {
        self.validate_common()?;
        if self.peers.is_empty() {
            return Err("profile has no [Peer] section".into());
        }
        if !self.peers.iter().any(|p| p.endpoint.is_some()) {
            return Err("no [Peer] has an Endpoint, so there is nothing to connect to".into());
        }
        if self.peers.iter().all(|p| p.allowed_ips.is_empty()) {
            return Err("no [Peer] has AllowedIPs, so no traffic would use the tunnel".into());
        }
        Ok(())
    }

    /// Checks that make sense for running as a server.
    pub fn validate_server(&self) -> Result<(), String> {
        self.validate_common()?;
        if self.interface.listen_port.is_none() {
            return Err("server config needs a ListenPort".into());
        }
        Ok(())
    }

    fn validate_common(&self) -> Result<(), String> {
        if self.interface.addresses.is_empty() {
            return Err("[Interface] has no Address".into());
        }
        let own = self.interface.private_key.public_key();
        let mut seen = std::collections::HashSet::new();
        for p in &self.peers {
            if p.public_key == own {
                return Err("a [Peer] uses this interface's own public key".into());
            }
            if !seen.insert(p.public_key) {
                return Err(format!("duplicate peer public key {}", p.public_key.short()));
            }
        }
        Ok(())
    }

    pub fn mtu(&self) -> u16 {
        self.interface.mtu.unwrap_or(DEFAULT_MTU)
    }
}

fn join(nets: &[IpNet]) -> String {
    nets.iter().map(ToString::to_string).collect::<Vec<_>>().join(", ")
}

fn parse_name_comment(comment: &str) -> Option<String> {
    let c = comment.trim();
    let rest = c.get(..4).filter(|p| p.eq_ignore_ascii_case("name")).map(|_| &c[4..])?;
    let rest = rest.trim_start();
    let rest = rest.strip_prefix('=').or_else(|| rest.strip_prefix(':'))?;
    let name = rest.trim();
    (!name.is_empty()).then(|| name.to_string())
}

fn is_domain(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 253
        && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '.' || c == '_')
        && !s.starts_with('.')
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "\u{feff}# exported by some provider
[Interface]
PrivateKey = yAnz5TF+lXXJte14tji3zlMNq+hd2rYUIgJBgB3fBmk=
Address = 10.66.0.2/32, fd00:66::2/128
DNS = 1.1.1.1, 2606:4700:4700::1111, corp.example
MTU = 1380
PostUp = iptables -A FORWARD -j ACCEPT

[Peer]
# Name = home server
PublicKey = xTIBA5rboUvnH4htodjb6e697QjLERt1NAB4mZqp8Dg=
PresharedKey = /UwcSPg38hW/D9Y3tcS1FOV0K1wuURMbS0sesJEP5ak=
AllowedIPs = 0.0.0.0/0, ::/0 # everything
Endpoint = vpn.example.com:51820
PersistentKeepalive = 25
";

    #[test]
    fn parses_typical_config() {
        let parsed = Config::parse(SAMPLE).unwrap();
        let c = &parsed.config;
        assert_eq!(c.interface.addresses.len(), 2);
        assert_eq!(c.interface.dns.len(), 2);
        assert_eq!(c.interface.dns_search, vec!["corp.example".to_string()]);
        assert_eq!(c.interface.mtu, Some(1380));
        assert_eq!(c.peers.len(), 1);
        let p = &c.peers[0];
        assert_eq!(p.name.as_deref(), Some("home server"));
        assert_eq!(p.allowed_ips.len(), 2);
        assert_eq!(p.endpoint, Some(Endpoint { host: "vpn.example.com".into(), port: 51820 }));
        assert_eq!(p.persistent_keepalive, Some(25));
        assert_eq!(parsed.warnings.len(), 1, "PostUp should be reported");
        c.validate_client().unwrap();
    }

    #[test]
    fn roundtrip() {
        let c = Config::parse(SAMPLE).unwrap().config;
        let again = Config::parse(&c.to_wg_string()).unwrap();
        assert_eq!(c, again.config);
        assert!(again.warnings.is_empty());
    }

    #[test]
    fn endpoint_forms() {
        assert_eq!("[2001:db8::1]:51820".parse::<Endpoint>().unwrap().to_string(), "[2001:db8::1]:51820");
        assert_eq!("1.2.3.4:1".parse::<Endpoint>().unwrap().port, 1);
        assert!("2001:db8::1:51820".parse::<Endpoint>().is_err());
        assert!("host".parse::<Endpoint>().is_err());
        assert!("host:0".parse::<Endpoint>().is_err());
    }

    #[test]
    fn reports_line_numbers() {
        let e = Config::parse("[Interface]\nPrivateKey = nope\n").unwrap_err();
        assert_eq!(e.line, 2);
        let e = Config::parse("Address = 1.2.3.4\n").unwrap_err();
        assert_eq!(e.line, 1);
        let e = Config::parse("[Interface]\n[Bogus]\n").unwrap_err();
        assert_eq!(e.line, 2);
    }

    #[test]
    fn missing_pieces() {
        assert!(Config::parse("").is_err());
        assert!(Config::parse("[Interface]\nAddress = 10.0.0.1/24\n").is_err());
        let txt = "[Interface]\nPrivateKey = yAnz5TF+lXXJte14tji3zlMNq+hd2rYUIgJBgB3fBmk=\n[Peer]\nAllowedIPs = 0.0.0.0/0\n";
        assert_eq!(Config::parse(txt).unwrap_err().line, 3);
    }

    #[test]
    fn bare_address_is_host_route() {
        assert_eq!(parse_net("10.0.0.1").unwrap().to_string(), "10.0.0.1/32");
        assert_eq!(parse_net("fd00::1").unwrap().to_string(), "fd00::1/128");
    }

    #[test]
    fn keepalive_off_and_zero() {
        let base = "[Interface]\nPrivateKey = yAnz5TF+lXXJte14tji3zlMNq+hd2rYUIgJBgB3fBmk=\n[Peer]\nPublicKey = xTIBA5rboUvnH4htodjb6e697QjLERt1NAB4mZqp8Dg=\n";
        for v in ["off", "0"] {
            let c = Config::parse(&format!("{base}PersistentKeepalive = {v}\n")).unwrap().config;
            assert_eq!(c.peers[0].persistent_keepalive, None);
        }
    }
}
